/**
 * Reuse workspace package compilation only inside the current GitHub CI job.
 * A receipt binds every source, lockfile, build recipe, and generated byte to
 * that job. It is never uploaded or cached, and standalone builds always build.
 */
import { createHash } from 'node:crypto'
import { execFileSync } from 'node:child_process'
import { existsSync, readFileSync, readdirSync, realpathSync, statSync, writeFileSync } from 'node:fs'
import { join } from 'node:path'

/** Resolve a job-local receipt; no caller-controlled repository file is trusted. */
export function proofContext(environment = process.env, directory = process.cwd()) {
  const isEnabled = environment.THALLY_CI_PACKAGE_BUILD_PROOF === 'true'
  if (environment.GITHUB_ACTIONS !== 'true' || environment.GITHUB_JOB !== 'verify' ||
      !/^\d+$/.test(environment.GITHUB_RUN_ID ?? '') || !/^\d+$/.test(environment.GITHUB_RUN_ATTEMPT ?? '') ||
      !isEnabled || !environment.RUNNER_TEMP) return null
  try {
    const receipt = join(realpathSync(environment.RUNNER_TEMP), 'thally-package-build-proof.json')
    return { receipt, identity: {
      directory: realpathSync(directory), node: process.version,
      nodeEnvironment: 'production',
      nodeOptions: environment.NODE_OPTIONS ?? null,
      run: environment.GITHUB_RUN_ID, attempt: environment.GITHUB_RUN_ATTEMPT,
      job: environment.GITHUB_JOB,
    } }
  } catch { return null }
}

function filesBelow(directory) {
  if (!existsSync(directory)) return []
  return readdirSync(directory, { withFileTypes: true }).sort((a, b) => a.name.localeCompare(b.name)).flatMap((entry) => {
    const path = join(directory, entry.name)
    return entry.isDirectory() ? filesBelow(path) : [path]
  })
}

function digestFiles(directory, paths) {
  const hash = createHash('sha256')
  for (const path of [...paths].sort()) {
    const absolute = join(directory, path)
    if (!existsSync(absolute)) {
      hash.update(JSON.stringify([path, null]))
      continue
    }
    if (!statSync(absolute).isFile()) throw new Error(`Build input is not a file: ${path}`)
    hash.update(JSON.stringify([path, readFileSync(absolute).toString('base64')]))
  }
  return hash.digest('hex')
}

/** Hash tracked and new inputs, including recipes and exact generated output. */
export function workspaceBuildState(directory = process.cwd()) {
  const inputs = execFileSync('git', ['ls-files', '-z', '--cached', '--others', '--exclude-standard', '--',
    '.'],
    { cwd: directory, encoding: 'utf8' }).split('\0').filter(Boolean)
    .filter((path) => !path.split('/').some((part) => ['dist', 'node_modules', '.turbo'].includes(part)))
  const packages = readdirSync(join(directory, 'packages')).filter((name) => existsSync(join(directory, 'packages', name, 'package.json')))
  const outputs = packages.flatMap((name) => {
    const files = filesBelow(join(directory, 'packages', name, 'dist'))
    if (!files.length) throw new Error(`No built outputs for ${name}`)
    return files.map((file) => file.slice(directory.length + 1))
  })
  if (!inputs.length || !outputs.length) throw new Error('Build proof requires inputs and outputs')
  return { inputs: digestFiles(directory, inputs), outputs: digestFiles(directory, outputs) }
}

/** A stale, incomplete, moved, or unreadable receipt always triggers a rebuild. */
export function hasCurrentWorkspaceBuild(context) {
  if (!context) return false
  try {
    const proof = JSON.parse(readFileSync(context.receipt, 'utf8'))
    return JSON.stringify(proof.identity) === JSON.stringify(context.identity) &&
      JSON.stringify(proof.state) === JSON.stringify(workspaceBuildState(context.identity.directory))
  } catch { return false }
}

/** Record success only after every package compiler has exited successfully. */
export function recordWorkspaceBuild(context) {
  if (context) writeFileSync(context.receipt, JSON.stringify({ identity: context.identity, state: workspaceBuildState(context.identity.directory) }))
}
